svg.script:
(function() {
  const outline = document.getElementById('outlineText1080');
  const filled = document.getElementById('filledText1080');
  const clipRect = document.getElementById('clipRect1080');
  if (!outline || !filled || !clipRect) return;

  const DURATION = 3800;
  const PAUSE = 1000;
  const TOTAL = DURATION + PAUSE;

  const Y_BOTTOM = 650;
  const Y_TOP = 430;
  const DELTA_Y = Y_BOTTOM - Y_TOP;

  let startTime = null;

  function update(timestamp) {
    if (!startTime) startTime = timestamp;
    const elapsed = (timestamp - startTime) % TOTAL;

    let pct = 1;
    let progress = 0;

    if (elapsed <= DURATION) {
      const t = elapsed / DURATION;
      progress = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
      pct = Math.min(100, Math.max(1, Math.round(progress * 99) + 1));
    } else {
      progress = 1.0;
      pct = 100;
    }

    const currentY = Y_BOTTOM - (progress * DELTA_Y);
    clipRect.setAttribute('y', currentY.toFixed(1));

    const str = pct + '%';
    if (outline.textContent !== str) {
      outline.textContent = str;
      filled.textContent = str;
    }

    requestAnimationFrame(update);
  }

  requestAnimationFrame(update);
})();
